.fplate__cols { grid-template-columns: repeat(2, minmax(0px, 1fr)); align-items: start; }
}
.fplate__map { position: relative; display: grid; grid-template-columns: repeat(5, minmax(0px, 1fr)); gap: var(--bw-heavy); margin-top: var(--space-3); border: var(--bw-heavy) solid var(--border-stamped); background: var(--border-stamped); }
.fplate__cell { display: flex; align-items: center; justify-content: center; min-width: 0px; aspect-ratio: 1 / 1; overflow: hidden; padding: 0px; border: 0px; color: var(--text-heading); font-family: var(--font-mono); font-size: var(--fs-small); font-weight: var(--w-bold); cursor: pointer; }
.fplate__cell small { font-size: 0.6em; }
.fplate__cell:focus-visible { outline: 3px solid var(--focus-ring); outline-offset: -3px; }
.fplate__box { position: absolute; top: 20%; left: 20%; width: 60%; height: 60%; border: 3px solid var(--border-stamped); pointer-events: none; }
.fplate__cell[data-band="0"], .fplate__swatch[data-band="0"] { background: var(--clay); color: var(--text-on-ink); }
.fplate__cell[data-band="1"], .fplate__swatch[data-band="1"] { background: var(--field-dirt); }
.fplate__cell[data-band="2"], .fplate__swatch[data-band="2"] { background: var(--field-outfield); }
.fplate__cell[data-band="3"], .fplate__swatch[data-band="3"] { background: var(--field-mint); }
