.fplate__ramp { display: flex; align-items: stretch; margin-top: var(--space-3); border: var(--bw-heavy) solid var(--border-stamped); }
.fplate__swatch { flex: 1 1 0px; height: var(--space-4); }
.fplate__endcap { padding: 0 var(--space-2); font-family: var(--font-display); font-size: var(--fs-label); font-weight: var(--w-bold); letter-spacing: var(--ls-label); text-transform: uppercase; white-space: nowrap; }
.fplate__endcap--bad { color: var(--clay-deep); }
.fplate__endcap--good { color: var(--accent-positive); }
.fplate__read { display: flex; flex-direction: column; gap: var(--space-1); min-height: calc(var(--space-16) + var(--space-4)); margin-top: var(--space-4); padding: var(--space-3h) var(--space-4); border: var(--bw-heavy) solid var(--border-stamped); background: var(--field-wash); }
.fplate__readtitle { color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-title-md); font-weight: var(--w-bold); line-height: var(--lh-solid); text-transform: uppercase; }
.fplate__readtext { color: var(--text-muted); font-family: var(--font-mono); font-size: var(--fs-cell); }
.fplate__facts { margin-top: var(--space-4); }
