.fplate__figs { display: block; color: var(--text-muted); font-family: var(--font-mono); font-size: var(--fs-cell); }
@media (hover: hover) {
.logtable__grid tbody tr:not(.logtable__div, :has(a, button)):hover { background: var(--surface-row-hover); }
}
